policies.inbound:



    {{hub-api-audience}}
    {{hub-api-bare-audience}}



      {{hub-delegated-scope}}


      {{entra-tenant-id}}












      __ENTRA_LOGIN_ENDPOINT__{{entra-tenant-id}}/oauth2/v2.0/token
      POST

        application/x-www-form-urlencoded

      @{
        var caller = context.Request.Headers.GetValueOrDefault("Authorization", "").Split(' ').Last();
        var assertion = (string)context.Variables["hubClientAssertion"];
        return "grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer"
            + "&client_id={{hub-client-id}}"
            + "&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer"
            + "&client_assertion=" + System.Net.WebUtility.UrlEncode(assertion)
            + "&assertion=" + System.Net.WebUtility.UrlEncode(caller)
            + "&scope=" + System.Net.WebUtility.UrlEncode("{{adapter-delegated-scope}}")
            + "&requested_token_use=on_behalf_of";
      }







            application/json


            @{
              if (!context.Variables.ContainsKey("hubOboResponse")) { return "Bearer error=\"invalid_token\""; }
              var failure = ((IResponse)context.Variables["hubOboResponse"]).Body.As<JObject>(preserveContent: true);
              return "Bearer error=\"" + ((string)failure["error"] ?? "invalid_token") + "\"";
            }

          @{
            var code = "";
            var error = "delegation_failed";
            if (context.Variables.ContainsKey("hubOboResponse"))
            {
                var failure = ((IResponse)context.Variables["hubOboResponse"]).Body.As<JObject>(preserveContent: true);
                error = (string)failure["error"] ?? error;
                var description = (string)failure["error_description"] ?? "";
                var separator = description.IndexOf(':');
                code = description.StartsWith("AADSTS") && separator > 0
                    ? description.Substring(0, separator)
                    : "";
            }
            return new JObject(
                new JProperty("error", error),
                new JProperty("entraErrorCode", code),
                new JProperty("message",
                    "The API Hub could not obtain a delegated adapter token for this user. "
                    + "Check the hub-to-adapter grant and any Conditional Access requirement.")
            ).ToString();
          }









  @("Bearer " + (string)context.Variables["adapterToken"])

__REQUEST_VALIDATION__
